/bin/zsh -lc "find . -type f -print | awk '
BEGIN { IGNORECASE=1; count=0 }
{
  n="'$0
  sub(/''^.*'"\\//, \"\", n)
  if (n "'!~ /'"\\./) next
  ext=n
  sub(/"'^.*'"\\./, \"\", ext)
  if (ext ~ /"'^(pdf|doc|docx|odt|rtf|txt|md|markdown|csv|tsv|xls|xlsx|ods|ppt|pptx|odp|epub|pages|numbers)$/) count++
}
END { print count }
'"'"

